def dehydrate_timedelta(value):
    """Dehydrate a datetime.timedelta into a JSON‑serializable representation."""
    if value is None:
        return None
    return {
        "days": value.days,
        "seconds": value.seconds,
        "microseconds": value.microseconds,
    }

def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    if value is None:
        return None
    return value.isoformat()

def dehydrate_point(value):
    """Dehydrator for Point data."""
    # If the point is a namedtuple or similar, use _asdict to get a dict
    if hasattr(value, "_asdict"):
        return value._asdict()
    # If the point is a dataclass or has a __dict__, return that
    if hasattr(value, "__dict__"):
        return value.__dict__
    # If the point is already a sequence, return it as a list
    if isinstance(value, (list, tuple)):
        return list(value)
    # Fallback: return a string representation
    return str(value)

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    return list(self._record.keys())

def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    for idx, item in enumerate(self._data):
        if item == key:
            return idx
    raise ValueError(f"{key} is not in list")

def values(self, *keys):
    """Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # If no keys are provided, return all values
    if not keys:
        if isinstance(self._data, dict):
            return list(self._data.values())
        else:
            return list(self._data)

    # Prepare the result list
    result = []

    # Handle dictionary-like data
    if isinstance(self._data, dict):
        items = list(self._data.items())
        for k in keys:
            if isinstance(k, int):
                if k < 0 or k >= len(items):
                    raise IndexError(f"Index {k} out of range")
                result.append(items[k][1])
            else:
                if k not in self._data:
                    raise KeyError(f"Key {k!r} not found")
                result.append(self._data[k])
    # Handle sequence-like data (list, tuple, etc.)
    else:
        seq = list(self._data)
        for k in keys:
            if not isinstance(k, int):
                raise TypeError(f"Index must be an int, got {type(k).__name__}")
            if k < 0 or k >= len(seq):
                raise IndexError(f"Index {k} out of range")
            result.append(seq[k])

    return result

def data(self, *keys):
    """
    Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key.
    Keys provided in the items that are not in the record will be
    inserted with a value of None; indexes provided that are out of
    bounds will trigger an IndexError.
    """
    # Try to get the record's field names and values
    fields = getattr(self, "_fields", None)
    values = getattr(self, "_values", None)

    # Fallback: if the object behaves like a dict, just return a dict
    if fields is None or values is None:
        if not keys:
            return dict(self)
        return {k: self.get(k) for k in keys}

    # If no keys are specified, return all fields
    if not keys:
        return dict(zip(fields, values))

    result = {}
    for key in keys:
        if isinstance(key, int):
            # Index-based access
            if key < 0 or key >= len(values):
                raise IndexError(f"Index {key} out of bounds")
            result[fields[key]] = values[key]
        else:
            # Key-based access
            if key in fields:
                idx = fields.index(key)
                result[key] = values[idx]
            else:
                result[key] = None
    return result

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    srid = srid_map.get(name)
    def __init__(self, x, y, **kwargs):
        Point.__init__(self, x, y)
        for f in fields:
            setattr(self, f, kwargs.get(f))
        if srid is not None:
            self.srid = srid
    attrs = {'__init__': __init__}
    if srid is not None:
        attrs['srid'] = srid
    return type(name, (Point,), attrs)

def deprecated(message):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def cached(cache, key=hashkey, lock=None):
    def decorator(func):
        def wrapper(*args, **kwargs):
            k = key(args, kwargs)
            if lock:
                with lock:
                    if k in cache:
                        return cache[k]
                    result = func(*args, **kwargs)
                    cache[k] = result
                    return result
            else:
                if k in cache:
                    return cache[k]
                result = func(*args, **kwargs)
                cache[k] = result
                return result
        return wrapper
    return decorator

def setdefault(self, key, default=None):
    """
    D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D
    """
    if key in self:
        return self[key]
    else:
        self[key] = default
        return default

def get(self, key, default=None):
    """
    D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None.
    """
    try:
        return self[key]
    except KeyError:
        return default

