    )

def difference(d1, d2, level=-1):
    """
    Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1, if a key is present both in *d1* and *d2*
    but has different values, it is included into the difference.
    """
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        return {}

    result = {}
    for key, val1 in d1.items():
        if key not in d2:
            result[key] = val1
        else:
            val2 = d2[key]
            # If both values are dicts and we are allowed to recurse
            if isinstance(val1, dict) and isinstance(val2, dict) and (level == -1 or level > 1):
                sublevel = level - 1 if level > 1 else -1
                subdiff = difference(val1, val2, sublevel)
                if subdiff:
                    result[key] = subdiff
            else:
                # Include if values differ
                if val1 != val2:
                    result[key] = val1
    return result

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    import re
    from collections.abc import Iterable

    # Simple regex patterns for demonstration purposes.
    # Keys and values must start and end with an alphanumeric character.
    # They may contain alphanumerics, underscores, hyphens, or dots in between.
    # Empty string is allowed for values.
    KEY_REGEX = re.compile(r'^[A-Za-z0-9]([A-Za-z0-9_.-]*[A-Za-z0-9])?$')
    VALUE_REGEX = re.compile(r'^$|^[A-Za-z0-9]([A-Za-z0-9_.-]*[A-Za-z0-9])?$')

    errors = []

    for key, value in labels.items():
        # Validate key
        if not isinstance(key, str):
            errors.append({str(key): 'expected string or bytes-like object'})
        else:
            if not KEY_REGEX.match(key):
                errors.append({key: f"Label key '{key}' does not match the regex"})

        # Validate value(s)
        # If the value is an iterable (but not a string), treat each element separately.
        if isinstance(value, Iterable) and not isinstance(value, (str, bytes)):
            for item in value:
                if not isinstance(item, str):
                    errors.append({str(value): 'expected string or bytes-like object'})
                else:
                    if not VALUE_REGEX.match(item):
                        errors.append({str(value): f"Label value '{item}' does not match the regex"})
        else:
            if not isinstance(value, str):
                errors.append({str(value): 'expected string or bytes-like object'})
            else:
                if not VALUE_REGEX.match(value):
                    errors.append({str(value): f"Label value '{value}' does not match the regex"})

    if errors:
        raise ValidationError(errors)

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Recursively generate a default observer_schema dictionary from a Kubernetes
    resource manifest. Non-dict and non-list values are replaced with None.
    When first_level is True, identifying fields (apiVersion, kind, metadata.name,
    metadata.namespace) are copied from the original manifest.
    """
    result = {}
    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            # Recurse into nested dictionaries
            result[key] = generate_default_observer_schema_dict(value, first_level=False)
        elif isinstance(value, list):
            # Delegate list handling to the corresponding helper
            result[key] = generate_default_observer_schema_list(value, first_level=False)
        else:
            # Replace scalar values with None
            result[key] = None

    if first_level:
        # Preserve identifying fields from the original manifest
        for id_field in ("apiVersion", "kind"):
            if id_field in manifest_dict:
                result[id_field] = manifest_dict[id_field]

        # Preserve metadata name and namespace if present
        if "metadata" in manifest_dict and isinstance(manifest_dict["metadata"], dict):
            meta = result.get("metadata", {})
            for meta_field in ("name", "namespace"):
                if meta_field in manifest_dict["metadata"]:
                    meta[meta_field] = manifest_dict["metadata"][meta_field]
            result["metadata"] = meta

    return result

def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    # Ensure last_applied_manifest is a list
    if last_applied_manifest is None:
        last_applied_manifest = []
    if not isinstance(last_applied_manifest, list):
        # If it's not a list, we cannot update; return as is
        return last_applied_manifest
    if observer_schema is None:
        return last_applied_manifest
    if response is None:
        return last_applied_manifest
    # Iterate over schema
    for idx, field in enumerate(observer_schema):
        # Determine expected type
        field_type = field.get('type')
        # Get response value if available
        resp_val = None
        if isinstance(response, list) and idx < len(response):
            resp_val = response[idx]
        # Infer type if not specified
        if field_type is None:
            if isinstance(resp_val, dict):
                field_type = 'dict'
            elif isinstance(resp_val, list):
                field_type = 'list'
            else:
                field_type = 'scalar'
        # Ensure last_applied_manifest has entry
        if idx >= len(last_applied_manifest):
            # Initialize based on type
            if field_type == 'dict':
                last_applied_manifest.append({})
            elif field_type == 'list':
                last_applied_manifest.append([])
            else:
                last_applied_manifest.append(None)
        # Update based on type
        if field_type == 'dict':
            # Ensure dict
            if not isinstance(last_applied_manifest[idx], dict):
                last_applied_manifest[idx] = {}
            child_schema = field.get('children', [])
            child_resp = resp_val if isinstance(resp_val, dict) else {}
            update_last_applied_manifest_dict_from_resp(last_applied_manifest[idx], child_schema, child_resp)
        elif field_type == 'list':
            # Ensure list
            if not isinstance(last_applied_manifest[idx], list):
                last_applied_manifest[idx] = []
            if isinstance(resp_val, list):
                # Ensure list length
                for j, item in enumerate(resp_val):
                    if j >= len(last_applied_manifest[idx]):
                        # Initialize element
                        if isinstance(item, dict):
                            last_applied_manifest[idx].append({})
                        elif isinstance(item, list):
                            last_applied_manifest[idx].append([])
                        else:
                            last_applied_manifest[idx].append(None)
                    # Update element
                    if isinstance(item, dict):
                        child_schema = field.get('children', [])
                        update_last_applied_manifest_dict_from_resp(last_applied_manifest[idx][j], child_schema, item)
                    elif isinstance(item, list):
                        child_schema = field.get('children', [])
                        update_last_applied_manifest_list_from_resp(last_applied_manifest[idx][j], child_schema, item)
                    else:
                        last_applied_manifest[idx][j] = item
        else:
            # scalar
            if resp_val is not None:
                last_applied_manifest[idx] = resp_val
    return last_applied_manifest

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Base default schema that observes all top‑level fields of a resource
    base_default_schema = {
        "$schema": "http://json-schema.org/draft-07/schema#",
        "type": "object",
        "properties": {
            "metadata": {"type": "object"},
            "spec": {"type": "object"},
            "status": {"type": "object"},
        },
    }

    # Start with the user‑provided observer schema if any
    observer_schema = getattr(app.spec, "observer_schema", {}) or {}

    # Ensure we don't modify the original mapping
    observer_schema = dict(observer_schema)

    # Iterate over all resources in the manifest
    for resource in getattr(app.spec, "manifest", []):
        kind = resource.get("kind")
        if not kind:
            continue  # skip resources without a kind

        # If the kind is not already in the observer schema, add the default
        if kind not in observer_schema:
            # Create a fresh copy of the default schema for this kind
            observer_schema[kind] = {
                "$schema": base_default_schema["$schema"],
                "type": base_default_schema["type"],
                "properties": {
                    "metadata": {"type": "object"},
                    "spec": {"type": "object"},
                    "status": {"type": "object"},
                },
            }

    return observer_schema

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    import os

    # Resolve the root directory from the given path or pyfs root
    if isinstance(path, str):
        root = path
    else:
        # Try common pyfs attributes that expose the underlying path
        if hasattr(path, "path"):
            root = path.path
        elif hasattr(path, "get_path"):
            root = path.get_path()
        else:
            # Fallback: use the string representation (may not be a valid path)
            root = str(path)

    # The root must be an existing directory
    if not os.path.isdir(root):
        return False

    # Required components for a minimal OCFL object
    required = {
        "objects": os.path.isdir,
        "manifest": os.path.isfile,
        "config.json": os.path.isfile,
        "ocfl_version": os.path.isfile,
    }

    for name, check in required.items():
        full_path = os.path.join(root, name)
        if not check(full_path):
            return False

    # If all required components exist, consider the object valid
    return True

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    log = getattr(self, 'validation_log', [])
    if not log:
        return ''
    return "\n".join(prefix + str(item) for item in log)

def validate(self, inventory, extract_spec_version=False):
    if not isinstance(inventory, dict):
        raise ValueError("Inventory must be a dictionary")
    # Determine spec_version
    spec_version = self.spec_version
    type_to_version = {
        'component': '1.0',
        'service': '2.0',
        'application': '3.0',
    }
    if extract_spec_version:
        type_val = inventory.get('type')
        if type_val:
            spec_version = type_to_version.get(type_val, self.spec_version)
    # Ensure inventory has spec_version
    if 'spec_version' not in inventory:
        inventory['spec_version'] = spec_version
    # Validate spec_version format
    if not isinstance(inventory['spec_version'], str) or not inventory['spec_version']:
        raise ValueError("Invalid spec_version in inventory")
    # Validate required fields
    required_fields = ['name', 'type', 'spec_version']
    for field in required_fields:
        if field not in inventory:
            raise ValueError(f"Missing required field: {field}")
    # Validate name
    if not isinstance(inventory['name'], str) or not inventory['name'].strip():
        raise ValueError("Invalid name in inventory")
    # Validate type
    if inventory['type'] not in type_to_version:
        raise ValueError(f"Unsupported type: {inventory['type']}")
    # Validate spec_version consistency
    if inventory['spec_version'] != spec_version:
        raise ValueError(f"spec_version mismatch: expected {spec_version}")
    # Validate components if present
    if 'components' in inventory:
        comps = inventory['components']
        if not isinstance(comps, list):
            raise ValueError("components must be a list")
        for comp in comps:
            if not isinstance(comp, dict):
                raise ValueError("Each component must be a dict")
            if 'name' not in comp or 'type' not in comp:
                raise ValueError("Component missing required fields")
    return True

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Ensure prior is the same type as self
    if not isinstance(prior, type(self)):
        raise TypeError(f"prior must be an instance of {type(self).__name__}")

    # Ensure prior has the expected attributes
    if not hasattr(prior, "version") or not hasattr(self, "version"):
        raise AttributeError("Both self and prior must have a 'version' attribute")
    if not hasattr(prior, "inventory") or not hasattr(self, "inventory"):
        raise AttributeError("Both self and prior must have an 'inventory' attribute")

    # Check that prior's version is strictly less than the current version
    if prior.version >= self.version:
        raise ValueError(
            f"Prior version ({prior.version}) must be less than current version ({self.version})"
        )

    # Ensure inventories are dictionaries (or at least mapping types)
    if not isinstance(prior.inventory, dict) or not isinstance(self.inventory, dict):
        raise TypeError("Both inventories must be dictionaries mapping item identifiers to items")

    # Check that every item in the prior inventory exists in the current inventory
    missing_items = set(prior.inventory) - set(self.inventory)
    if missing_items:
        raise ValueError(
            f"The following items from the prior inventory are missing in the current inventory: {missing_items}"
        )

    # Optionally, verify that the items themselves are identical (or at least compatible)
    # Here we perform a shallow equality check; adjust as needed for your domain.
    for key, prior_item in prior.inventory.items():
        current_item = self.inventory[key]
        if prior_item != current_item:
            raise ValueError(
                f"Item mismatch for key '{key}': prior item {prior_item!r} differs from current item {current_item!r}"
            )

    # If all checks pass, return True (or simply complete without error)
    return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # If the requested version is not present, return an empty mapping.
    if version not in inventory:
        return {}

    # Sort the versions to ensure a deterministic order.
    sorted_versions = sorted(inventory.keys())

    # Find the index of the requested version.
    try:
        start_index = sorted_versions.index(version)
    except ValueError:
        return {}

    # Initialize the result with the logical paths from the requested version.
    result = {}
    base_state = inventory[version]
    for logical_path, files in base_state.items():
        # Ensure we store a set of files.
        result[logical_path] = set(files)

    # Iterate over all later versions and merge any files that belong to the
    # same logical paths. This captures references to duplicate files that
    # appear in later versions.
    for later_version in sorted_versions[start_index + 1 :]:
        state = inventory.get(later_version, {})
        for logical_path, files in state.items():
            if logical_path in result:
                result[logical_path].update(files)

    return result

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Basic type checks
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary mapping file names to checksums.")
    if not isinstance(manifest_files, (set, list, tuple)):
        raise ValueError("manifest_files must be a set, list, or tuple of file names.")
    # Ensure all manifest file names are strings
    if not all(isinstance(f, str) for f in manifest_files):
        raise ValueError("All manifest file names must be strings.")
    manifest_set = set(manifest_files)

    # Validate each entry in the fixity block
    for file_name, checksum in fixity.items():
        if not isinstance(file_name, str):
            raise ValueError(f"Fixity key '{file_name}' is not a string.")
        if file_name not in manifest_set:
            raise ValueError(f"Fixity references unknown file '{file_name}' not present in the manifest.")
        if not isinstance(checksum, str):
            raise ValueError(f"Checksum for file '{file_name}' must be a string.")
        # Basic checksum format validation: hex string of typical length
        if not all(c in "0123456789abcdefABCDEF" for c in checksum):
            raise ValueError(f"Checksum for file '{file_name}' contains non-hex characters.")
        if len(checksum) not in (32, 64):
            raise ValueError(f"Checksum for file '{file_name}' has invalid length {len(checksum)}; expected 32 (MD5) or 64 (SHA-256) characters.")
    # If all checks pass, return True
    return True

def select_filenames_by_prefix(prefix, files):
    import os
    return [f for f in files if os.path.basename(f).startswith(prefix)]

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    import os
    import xml.etree.ElementTree as ET

    data = {}
    for entry in os.listdir(folder):
        path = os.path.join(folder, entry)
        if not os.path.isfile(path):
            continue
        name, ext = os.path.splitext(entry)
        if name not in data:
            data[name] = {}
        ext_lower = ext.lower()
        if ext_lower == ".xml":
            try:
                tree = ET.parse(path)
                data[name]["xml"] = tree
            except Exception:
                data[name]["xml"] = None
        else:
            try:
                with open(path, "r", encoding="utf-8") as f:
                    content = f.read()
                data[name][ext_lower] = content
            except Exception:
                data[name][ext_lower] = None
    return data

