def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    # Work on a mutable list
    exprs = list(args)
    changed = True
    while changed:
        changed = False
        n = len(exprs)
        i = 0
        while i < n:
            e1 = exprs[i]
            j = i + 1
            while j < n:
                e2 = exprs[j]
                # Helper to drop an expression at index idx
                def drop(idx):
                    nonlocal exprs, n, changed
                    exprs.pop(idx)
                    n -= 1
                    changed = True

                # Absorption: A & (A | B) = A, A | (A & B) = A
                # Check if e1 is simple and e2 is a compound containing e1
                if not e1.is_And and not e1.is_Or:
                    if e2.is_Or and e1 in e2.args:
                        drop(j)
                        continue
                    if e2.is_And and e1 in e2.args:
                        drop(j)
                        continue
                # Check reverse: e2 simple and e1 contains e2
                if not e2.is_And and not e2.is_Or:
                    if e1.is_Or and e2 in e1.args:
                        drop(i)
                        break
                    if e1.is_And and e2 in e1.args:
                        drop(i)
                        break

                # Negative absorption: A & (~A | B) = A & B
                # and A | (~A & B) = A | B
                # e1 simple, e2 compound
                if not e1.is_And and not e1.is_Or:
                    # e2 is Or
                    if e2.is_Or:
                        # find Not(e1) in e2
                        not_e1 = None
                        for arg in e2.args:
                            if arg.is_Not and arg.args[0] == e1:
                                not_e1 = arg
                                break
                        if not_e1 is not None:
                            # other part(s)
                            others = [a for a in e2.args if a != e1 and a != not_e1]
                            if len(others) == 1:
                                B = others[0]
                            else:
                                B = e2.func(*others)
                            # replace e1 with e1 & B
                            exprs[i] = e1 & B
                            drop(j)
                            continue
                    # e2 is And
                    if e2.is_And:
                        not_e1 = None
                        for arg in e2.args:
                            if arg.is_Not and arg.args[0] == e1:
                                not_e1 = arg
                                break
                        if not_e1 is not None:
                            others = [a for a in e2.args if a != e1 and a != not_e1]
                            if len(others) == 1:
                                B = others[0]
                            else:
                                B = e2.func(*others)
                            exprs[i] = e1 | B
                            drop(j)
                            continue
                # e2 simple, e1 compound
                if not e2.is_And and not e2.is_Or:
                    # e1 is Or
                    if e1.is_Or:
                        not_e2 = None
                        for arg in e1.args:
                            if arg.is_Not and arg.args[0] == e2:
                                not_e2 = arg
                                break
                        if not_e2 is not None:
                            others = [a for a in e1.args if a != e2 and a != not_e2]
                            if len(others) == 1:
                                B = others[0]
                            else:
                                B = e1.func(*others)
                            exprs[j] = e2 & B
                            drop(i)
                            break
                    # e1 is And
                    if e1.is_And:
                        not_e2 = None
                        for arg in e1.args:
                            if arg.is_Not and arg.args[0] == e2:
                                not_e2 = arg
                                break
                        if not_e2 is not None:
                            others = [a for a in e1.args if a != e2 and a != not_e2]
                            if len(others) == 1:
                                B = others[0]
                            else:
                                B = e1.func(*others)
                            exprs[j] = e2

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    import sys
    if sys.version_info[0] < 3:
        def wrapper(self, *args, **kwargs):
            name = namefunc(self, *args, **kwargs)
            if isinstance(name, unicode):
                return name.encode('utf-8')
            return name
        return wrapper
    else:
        return namefunc

def get_versions():
    """Get version information or return default if unable to do so."""
    # Try to get the version using importlib.metadata (Python 3.8+)
    try:
        from importlib.metadata import version, PackageNotFoundError
    except ImportError:
        # Fallback for older Python versions that have importlib_metadata backport
        try:
            from importlib_metadata import version, PackageNotFoundError
        except ImportError:
            version = None
    if version:
        try:
            # __package__ may be None when run as a script; use a placeholder
            pkg_name = __package__ or "unknown"
            return version(pkg_name)
        except PackageNotFoundError:
            pass
    # Fallback: read a VERSION file in the same directory as this module
    try:
        import os
        base_dir = os.path.abspath(os.path.dirname(__file__))
        with open(os.path.join(base_dir, "VERSION"), "r", encoding="utf-8") as f:
            return f.read().strip()
    except Exception:
        pass
    # Default version if all else fails
    return "0.0.0"

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Extract pieces
    if isinstance(pieces, dict):
        major = pieces.get('major')
        minor = pieces.get('minor')
        patch = pieces.get('patch')
        pre = pieces.get('pre_release')
        build = pieces.get('build')
    else:
        # Assume list/tuple: [major, minor, patch, pre_release, build]
        major = pieces[0] if len(pieces) > 0 else None
        minor = pieces[1] if len(pieces) > 1 else None
        patch = pieces[2] if len(pieces) > 2 else None
        pre = pieces[3] if len(pieces) > 3 else None
        build = pieces[4] if len(pieces) > 4 else None

    # If no major component, nothing to render
    if major is None:
        return ""

    # Base version string
    parts = [str(major)]
    if minor is not None:
        parts.append(str(minor))
    if patch is not None:
        parts.append(str(patch))
    base = ".".join(parts)

    # Pre-release handling
    if pre:
        if style == "semver":
            base += "-" + str(pre)
        elif style == "pep440":
            base += ".dev" + str(pre)
        elif style == "git":
            base += "-" + str(pre)
        else:
            base += "-" + str(pre)

    # Build metadata handling
    if build:
        if style == "semver":
            base += "+" + str(build)
        elif style == "pep440":
            base += "+post" + str(build)
        elif style == "git":
            base += "+" + str(build)
        else:
            base += "+" + str(build)

    # Git style prefix
    if style == "git":
        base = "v" + base

    return base

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    return '.' if any(p == '+' for p in pieces) else '+'

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Build the command list
    if isinstance(commands, (list, tuple)):
        cmd = list(commands)
    else:
        cmd = [commands]
    cmd.extend(args)

    # Prepare subprocess parameters
    kwargs = {
        'cwd': cwd,
        'env': env,
        'stdout': subprocess.PIPE,
        'stderr': subprocess.PIPE if not hide_stderr else subprocess.DEVNULL,
        'text': True
    }

    if verbose:
        print(f"Running command: {' '.join(cmd)}")

    result = subprocess.run(cmd, **kwargs)

    return result

def register_vcs_handler(vcs, method):
