    return method

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    # Retrieve objects from the root; support both a get_objects() method and a direct objects attribute
    objects = getattr(self.root, 'get_objects', lambda: getattr(self.root, 'objects', []))()

    for obj in objects:
        num_objects += 1
        valid = True

        if validate_objects:
            try:
                if hasattr(obj, 'validate'):
                    valid = obj.validate()
                else:
                    # Fallback: assume an 'is_valid' attribute or default to True
                    valid = getattr(obj, 'is_valid', True)
            except Exception as e:
                valid = False
                if show_warnings:
                    print(f"Warning: validation error for {obj}: {e}")

        if check_digests and valid:
            try:
                digest = getattr(obj, 'digest', None)
                expected = getattr(obj, 'expected_digest', None)
                if digest is not None and expected is not None:
                    if digest != expected:
                        valid = False
                        if show_warnings:
                            print(f"Warning: digest mismatch for {obj}")
            except Exception as e:
                valid = False
                if show_warnings:
                    print(f"Warning: digest check error for {obj}: {e}")

        if valid:
            good_objects += 1

    return num_objects, good_objects

