def deep_merge_nodes(nodes):
    """
    Merge a list of (ScalarNode, value_node) tuples, deep merging MappingNode values
    for duplicate keys. The last non-mapping value wins.
    """
    def merge_nodes(node1, node2):
        # If both are MappingNode, deep merge their contents
        if isinstance(node1, ruamel.yaml.nodes.MappingNode) and isinstance(node2, ruamel.yaml.nodes.MappingNode):
            merged_value = deep_merge_nodes(node1.value + node2.value)
            return ruamel.yaml.nodes.MappingNode(node1.tag, merged_value)
        # Otherwise, the second node wins
        return node2

    result = []
    key_index = {}
    for key_node, value_node in nodes:
        key_val = key_node.value
        if key_val in key_index:
            idx = key_index[key_val]
            existing_key_node, existing_value_node = result[idx]
            merged_value_node = merge_nodes(existing_value_node, value_node)
            result[idx] = (existing_key_node, merged_value_node)
        else:
            result.append((key_node, value_node))
            key_index[key_val] = len(result) - 1
    return result

