def deep_merge_nodes(nodes):
    """
    Merge a list of (ScalarNode key, Node value) tuples, deep merging MappingNode values
    for duplicate keys. Non-MappingNode values are overwritten by the last occurrence.
    """
    # Helper to merge two MappingNode values
    def merge_mapping_nodes(node1, node2):
        # node1 and node2 are MappingNode instances
        # Merge node2 into node1, returning a new MappingNode
        merged_pairs = []
        # Build a dict from node1's pairs for quick lookup
        seen = {}
        for k, v in node1.value:
            seen[k.value] = (k, v)
        # Process node2 pairs
        for k2, v2 in node2.value:
            key_val = k2.value
            if key_val in seen:
                k1, v1 = seen[key_val]
                # If both values are MappingNode, merge recursively
                if isinstance(v1, ruamel.yaml.nodes.MappingNode) and isinstance(v2, ruamel.yaml.nodes.MappingNode):
                    merged_val = merge_mapping_nodes(v1, v2)
                else:
                    # Last wins
                    merged_val = v2
                seen[key_val] = (k1, merged_val)
            else:
                seen[key_val] = (k2, v2)
        # Preserve original order: first from node1, then any new from node2
        for k, v in node1.value:
            key_val = k.value
            if key_val in seen:
                merged_pairs.append(seen[key_val])
                del seen[key_val]
        for k, v in node2.value:
            key_val = k.value
            if key_val in seen:
                merged_pairs.append(seen[key_val])
                del seen[key_val]
        return ruamel.yaml.nodes.MappingNode(tag=node1.tag, value=merged_pairs)

    result = []
    key_index = {}  # maps key value to index in result
    for key_node, val_node in nodes:
        key_val = key_node.value
        if key_val in key_index:
            idx = key_index[key_val]
            existing_key, existing_val = result[idx]
            if isinstance(existing_val, ruamel.yaml.nodes.MappingNode) and isinstance(val_node, ruamel.yaml.nodes.MappingNode):
                merged_val = merge_mapping_nodes(existing_val, val_node)
                result[idx] = (existing_key, merged_val)
            else:
                # Last wins
                result[idx] = (existing_key, val_node)
        else:
            result.append((key_node, val_node))
            key_index[key_val] = len(result) - 1
    return result

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
