def parse_arguments(*unparsed_arguments):
    import argparse
    # Try to use a globally defined parser if available
    parser = globals().get('parser')
    if parser is None:
        parser = argparse.ArgumentParser()
    # Find the subparsers action if it exists
    subparsers_action = None
    for action in parser._actions:
        if isinstance(action, argparse._SubParsersAction):
            subparsers_action = action
            break
    # If no subparsers are defined, just parse all arguments
    if subparsers_action is None:
        ns = parser.parse_args(unparsed_arguments)
        return {'global': ns}
    # Parse known arguments to separate global and subparser arguments
    global_ns, remaining = parser.parse_known_args(unparsed_arguments)
    dest = subparsers_action.dest
    subparser_name = getattr(global_ns, dest, None)
    if not subparser_name:
        return {'global': global_ns}
    # Retrieve the specific subparser and parse its arguments
    subparser = subparsers_action.choices.get(subparser_name)
    if subparser is None:
        # Subparser not found; treat all as global
        return {'global': global_ns}
    sub_ns, _ = subparser.parse_known_args(remaining)
    return {'global': global_ns, subparser_name: sub_ns}

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    # Helper functions for counting
    def _count_list(lst):
        d = {}
        for x in lst:
            d[x] = d.get(x, 0) + 1
        return d

    def _dict_subtract(a, b):
        res = {}
        for k, v in a.items():
            diff = v - b.get(k, 0)
            if diff > 0:
                res[k] = diff
        return res

    def _dict_add(a, b):
        res = a.copy()
        for k, v in b.items():
            res[k] = res.get(k, 0) + v
        return res

    parsed = {}
    original_counts = _count_list(unparsed_arguments)
    consumed_counts = {}

    for name, parser in subparsers.items():
        ns, remaining = parser.parse_known_args(unparsed_arguments)
        parsed[name] = ns
        remaining_counts = _count_list(remaining)
        # Arguments consumed by this parser
        consumed_this = _dict_subtract(original_counts, remaining_counts)
        consumed_counts = _dict_add(consumed_counts, consumed_this)

    # Remaining arguments not claimed by any subparser
    remaining_counts = _dict_subtract(original_counts, consumed_counts)
    remaining_args = []
    for arg, count in remaining_counts.items():
        remaining_args.extend([arg] * count)

    return parsed, remaining_args

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    if not isinstance(size, str):
        raise TypeError("size must be a string")
    size = size.strip()
    if not size:
        raise ValueError("size string is empty")

    # Mapping of suffixes to multipliers (decimal units)
    suffixes = {
        "k": 1000,
        "m": 1000**2,
        "g": 1000**3,
        "t": 1000**4,
        "p": 1000**5,
        "e": 1000**6,
    }

    # Detect suffix
    suffix = None
    num_part = size

    # Handle cases like "1KB", "1MB", etc.
    if size[-1].isalpha():
        last_char = size[-1].lower()
        if last_char == "b" and len(size) >= 2 and size[-2].lower() in suffixes:
            suffix = size[-2].lower()
            num_part = size[:-2]
        else:
            suffix = last_char
            num_part = size[:-1]

    if suffix and suffix in suffixes:
        try:
            number = float(num_part)
        except ValueError:
            raise ValueError(f"Invalid numeric part: {num_part!r}")
        return int(round(number * suffixes[suffix]))
    else:
        # No suffix: interpret as plain integer
        try:
            return int(num_part)
        except ValueError:
            raise ValueError(f"Invalid size string: {size!r}")

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    for d in dicts:
        for key, value in d.items():
            result[key] = result.get(key, 0) + value
    return result

