def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        platform = 0 if __import__('sys').platform.startswith('win') else 1
    if platform == 1:
        # POSIX-like splitting
        tokens = []
        current = []
        in_single = False
        in_double = False
        escape = False
        for c in s:
            if escape:
                current.append(c)
                escape = False
                continue
            if c == '\\':
                escape = True
                continue
            if in_single:
                if c == "'":
                    in_single = False
                else:
                    current.append(c)
                continue
            if in_double:
                if c == '"':
                    in_double = False
                else:
                    current.append(c)
                continue
            if c.isspace():
                if current:
                    tokens.append(''.join(current))
                    current = []
                continue
            if c == "'":
                in_single = True
                continue
            if c == '"':
                in_double = True
                continue
            current.append(c)
        if escape:
            current.append('\\')
        if current:
            tokens.append(''.join(current))
        return tokens
    elif platform == 0:
        # Windows/CMD-like splitting
        tokens = []
        current = []
        in_quotes = False
        backslashes = 0
        i = 0
        length = len(s)
        while i < length:
            c = s[i]
            if c == '\\':
                backslashes += 1
                i += 1
                continue
            if c == '"':
                if backslashes % 2 == 0:
                    current.extend(['\\'] * (backslashes // 2))
                    in_quotes = not in_quotes
                else:
                    current.extend(['\\'] * ((backslashes - 1) // 2))
                    current.append('"')
                backslashes = 0
                i += 1
                continue
            if backslashes > 0:
                current.extend(['\\'] * backslashes)
                backslashes = 0
            if c.isspace() and not in_quotes:
                if current:
                    tokens.append(''.join(current))
                    current = []
                i += 1
                continue
            current.append(c)
            i += 1
        if backslashes > 0:
            current.extend(['\\'] * backslashes)
        if current:
            tokens.append(''.join(current))
        return tokens
    else:
        raise ValueError('Unsupported platform value: %r' % platform)

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None or str(frequency).strip().lower() == "always":
        return None

    freq = str(frequency).strip()
    import re
    match = re.match(r'^\s*(\d+(?:\.\d+)?)\s*([a-zA-Z]+)\s*$', freq)
    if not match:
        raise ValueError(f"Cannot parse frequency: {frequency}")

    value = float(match.group(1))
    unit = match.group(2).lower()

    if unit in ('day', 'days', 'd'):
        return datetime.timedelta(days=value)
    if unit in ('week', 'weeks', 'w'):
        return datetime.timedelta(weeks=value)
    if unit in ('hour', 'hours', 'h'):
        return datetime.timedelta(hours=value)
    if unit in ('minute', 'minutes', 'm'):
        return datetime.timedelta(minutes=value)
    if unit in ('second', 'seconds', 's'):
        return datetime.timedelta(seconds=value)

    raise ValueError(f"Unknown time unit in frequency: {frequency}")

def _resolve_string(matcher):
    name = matcher.group(1)
    default = matcher.group(2)
    value = os.getenv(name)
    if value is None:
        if default is not None:
            return default
        raise KeyError(f"Environment variable '{name}' not found and no default provided.")
    return value

def remove_ending_os_sep(input_list):
    if not isinstance(input_list, list):
        raise TypeError("input_list must be a list")
    processed = []
    for s in input_list:
        if not isinstance(s, str):
            raise TypeError("All items in input_list must be strings")
        if len(s) > 1 and s.endswith(os.sep):
            processed.append(s[:-1])
        else:
            processed.append(s)
    return processed

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if commands is None:
        raise ValueError("commands must not be None")
    if args is None:
        args = []
    if isinstance(commands, (list, tuple)):
        cmd = list(commands) + args
    else:
        cmd = [commands] + args
    if verbose:
        print(f"Running command: {' '.join(cmd)}")
    stderr = subprocess.DEVNULL if hide_stderr else subprocess.PIPE
    result = subprocess.run(
        cmd,
        cwd=cwd,
        env=env,
        stdout=subprocess.PIPE,
        stderr=stderr,
        text=True,
        check=True
    )
    return result.stdout

def is_ipv4(target):
    """ Test if IPv4 address or not
    """
    try:
        addr = ipaddress.ip_address(target)
    except ValueError:
        return False
    return isinstance(addr, ipaddress.IPv4Address)

