def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    return np.exp(-((x - 0.2)**2) / (2 * 0.1**2))

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    import json, os, logging, re
    configs = {}
    errors = []
    for filename in config_filenames:
        try:
            with open(filename, 'r') as f:
                data = json.load(f)
        except Exception as exc:
            record = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f'Failed to load configuration file {filename}: {exc}',
                args=None,
                exc_info=None
            )
            errors.append(record)
            continue
        # Apply overrides if provided
        if overrides:
            try:
                data.update(overrides)
            except Exception as exc:
                record = logging.LogRecord(
                    name='config_loader',
                    level=logging.ERROR,
                    pathname=filename,
                    lineno=0,
                    msg=f'Failed to apply overrides to {filename}: {exc}',
                    args=None,
                    exc_info=None
                )
                errors.append(record)
        # Resolve environment variables if requested
        if resolve_env:
            def resolve(value):
                if isinstance(value, str):
                    # Replace ${VAR} or $VAR patterns
                    def repl(match):
                        var = match.group(1) or match.group(2)
                        return os.getenv(var, '')
                    pattern = re.compile(r'\$\{([^}]+)\}|\$([A-Za-z_][A-Za-z0-9_]*)')
                    return pattern.sub(repl, value)
                elif isinstance(value, dict):
                    return {k: resolve(v) for k, v in value.items()}
                elif isinstance(value, list):
                    return [resolve(v) for v in value]
                else:
                    return value
            try:
                data = resolve(data)
            except Exception as exc:
                record = logging.LogRecord(
                    name='config_loader',
                    level=logging.ERROR,
                    pathname=filename,
                    lineno=0,
                    msg=f'Failed to resolve environment variables in {filename}: {exc}',
                    args=None,
                    exc_info=None
                )
                errors.append(record)
        configs[filename] = data
    return configs, errors

def protocol_handlers(cls, protocol_version=None):
    if protocol_version is not None and not isinstance(protocol_version, tuple):
        raise TypeError("protocol_version must be a tuple")
    if protocol_version is None:
        return dict(cls._protocol_handlers)
    handler = cls._protocol_handlers.get(protocol_version)
    return {protocol_version: handler} if handler else {}

def from_raw_values(cls, values):
        """Create a Bookmarks object from a list of raw bookmark string values.

        You should not need to use this method unless you want to deserialize
        bookmarks.

        :param values: ASCII string values (raw bookmarks)
        :type values: Iterable[str]
        """
        bookmarks = []
        for raw in values:
            if raw is None:
                continue
            raw = raw.strip()
            if not raw:
                continue
            try:
                bookmark = Bookmark.from_raw_value(raw)
            except Exception:
                bookmark = raw
            bookmarks.append(bookmark)
        return cls(bookmarks)

def _get_seq_with_type(seq, bufsize=None):
    from collections.abc import Sequence
    if isinstance(seq, Sequence):
        return seq, type(seq)
    if bufsize is not None:
        from itertools import islice
        derived = list(islice(seq, bufsize))
    else:
        derived = list(seq)
    return derived, type(derived)

def verifyObject(iface, candidate, tentative=False):
    errors = []
    # Skip providedBy check if tentative
    if not tentative:
        try:
            if not iface.providedBy(candidate):
                errors.append(f"{candidate!r} does not provide {iface!r}")
        except Exception as exc:
            errors.append(f"Error checking providedBy for {candidate!r}: {exc!r}")
    # Inspect interface names
    for name in iface.names():
        if not hasattr(candidate, name):
            errors.append(f"{candidate!r} missing attribute {name!r}")
            continue
        iface_attr = iface.get(name)
        cand_attr = getattr(candidate, name)
        # If interface attribute is callable, check signature
        if callable(iface_attr):
            try:
                inspect = __import__('inspect')
                iface_sig = inspect.signature(iface_attr)
                cand_sig = inspect.signature(cand_attr)
            except Exception as exc:
                errors.append(f"Could not inspect signature of {name!r}: {exc!r}")
                continue
            iface_params = list(iface_sig.parameters.values())
            cand_params = list(cand_sig.parameters.values())
            if len(iface_params) != len(cand_params):
                errors.append(
                    f"Signature mismatch for {name!r}: expected {len(iface_params)} params, got {len(cand_params)}"
                )
            else:
                for ip, cp in zip(iface_params, cand_params):
                    if ip.kind != cp.kind or ip.name != cp.name:
                        errors.append(
                            f"Signature mismatch for {name!r}: parameter {ip.name!r} kind {ip.kind} vs {cp.kind}"
                        )
                        break
        # Non-callable attributes require no further checks
    if errors:
        if len(errors) == 1:
            raise __import__('zope.interface').Invalid(errors[0])
        else:
            raise __import__('zope.interface').Invalid("\n".join(errors))
    return True

