def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Check for a public message
    if getattr(request, "public_message", None) or getattr(request, "is_public", False) or getattr(request, "public", False):
        return True

    # Check for a private message
    if getattr(request, "private_message", None) or getattr(request, "is_private", False) or getattr(request, "private", False):
        return True

    # Check for a legacy payload
    payload = getattr(request, "payload", None)
    if payload and isinstance(payload, dict):
        if payload.get("legacy") or payload.get("type") == "legacy":
            return True

    return False

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    # Attempt to get the request path
    path = None
    if hasattr(request, "path"):
        path = request.path
    elif hasattr(request, "url"):
        # Extract the path component from the URL (ignore query string)
        url = request.url
        path = url.split("?", 1)[0]
    # Check for the Matrix path prefix
    if path and path.startswith("/_matrix"):
        return True
    # Check for a Matrix‑specific header
    if hasattr(request, "headers"):
        headers = request.headers
        # Headers may be case‑insensitive; iterate over items
        for key, value in headers.items():
            if key.lower() == "x-matrix-request":
                return True
    return False

def format_dt(dt):
    """Format a datetime in the way that D* nodes expect."""
    # Convert to UTC if timezone-aware, otherwise assume UTC
    if dt.tzinfo is not None:
        dt = dt - dt.utcoffset()
    return dt.strftime("%Y-%m-%dT%H:%M:%SZ")

def fetch_content_type(url: str) -> Optional[str]:
    try:
        urllib = __import__('urllib.request')
        req = urllib.Request(url, method='HEAD')
        with urllib.urlopen(req) as resp:
            return resp.headers.get('Content-Type')
    except Exception:
        return None

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    # Tags must be non-empty, lowercase alphanumeric words optionally separated by single hyphens.
    # No leading/trailing hyphens, no consecutive hyphens, and length <= 30 characters.
    if not tag:
        return False
    if len(tag) > 30:
        return False
    # Ensure all characters are lowercase letters, digits, or hyphens
    for ch in tag:
        if not (ch.islower() or ch.isdigit() or ch == '-'):
            return False
    # No leading or trailing hyphen
    if tag[0] == '-' or tag[-1] == '-':
        return False
    # No consecutive hyphens
    if '--' in tag:
        return False
    return True

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    return {child.tag: child for child in node}

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    base = url.rstrip('/')
    if document_path:
        if not document_path.startswith('/'):
            document_path = '/' + document_path
        href = base + document_path
    else:
        href = base + '/.well-known/nodeinfo/2.0'
    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/2.0",
                "href": href
            }
        ]
    }

def parse_diaspora_webfinger(document: str) -> dict:
    import json
    import xml.etree.ElementTree as ET
    try:
        data = json.loads(document)
        subject = data.get('subject')
        aliases = data.get('aliases', [])
        if isinstance(aliases, str):
            aliases = [aliases]
        links = data.get('links', [])
        parsed_links = []
        for link in links:
            if isinstance(link, dict):
                parsed_links.append({
                    'rel': link.get('rel'),
                    'type': link.get('type'),
                    'href': link.get('href')
                })
        return {'subject': subject, 'aliases': aliases, 'links': parsed_links}
    except Exception:
        try:
            root = ET.fromstring(document)
            ns = {'xrd': 'http://docs.oasis-open.org/ns/xri/xrd-1.0'}
            subject_elem = root.find('xrd:subject', ns)
            subject = subject_elem.text if subject_elem is not None else None
            alias_elems = root.findall('xrd:alias', ns)
            aliases = [e.text for e in alias_elems if e.text]
            link_elems = root.findall('xrd:link', ns)
            parsed_links = []
            for e in link_elems:
                rel = e.attrib.get('rel')
                type_ = e.attrib.get('type')
                href = e.attrib.get('href')
                parsed_links.append({'rel': rel, 'type': type_, 'href': href})
            return {'subject': subject, 'aliases': aliases, 'links': parsed_links}
        except Exception as e:
            raise ValueError('Invalid webfinger document') from e

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    # Ensure settings_dirs is a list
    if isinstance(settings_dirs, str):
        dirs = [settings_dirs]
    else:
        dirs = list(settings_dirs)
    result = []
    for d in dirs:
        if not os.path.isdir(d):
            continue
        try:
            entries = os.listdir(d)
        except OSError:
            continue
        for entry in entries:
            full_path = os.path.join(d, entry)
            if not os.path.isfile(full_path):
                continue
            if spec_option is None:
                result.append(full_path)
                continue
            # If spec_option is a glob pattern
            if isinstance(spec_option, str) and (spec_option.startswith('*') or spec_option.startswith('?') or spec_option.startswith('[')):
                if fnmatch.fnmatch(entry, spec_option):
                    result.append(full_path)
                continue
            # If spec_option is an extension
            if isinstance(spec_option, str) and spec_option.startswith('.'):
                if entry.lower().endswith(spec_option.lower()):
                    result.append(full_path)
                continue
            # If spec_option is a regex pattern
            if isinstance(spec_option, re.Pattern):
                if spec_option.search(entry):
                    result.append(full_path)
                continue
            # If spec_option is a list or tuple of extensions
            if isinstance(spec_option, (list, tuple)):
                for ext in spec_option:
                    if isinstance(ext, str) and entry.lower().endswith(ext.lower()):
                        result.append(full_path)
                        break
                continue
            # If spec_option is a string exact match
            if isinstance(spec_option, str):
                if entry == spec_option:
                    result.append(full_path)
                continue
    return result

