def validate_from_content(cls, spec_content=None):
        """validates that spec (YAML) content has all required fields

        :param spec_content: content of spec file
        :raise IRValidatorException: when mandatory data
        is missing in spec file
        :return: Dictionary with data loaded from a spec (YAML) file
        """
        if spec_content is None:
            raise IRValidatorException("Spec content is None")

        # Load YAML if content is a string, otherwise assume dict
        if isinstance(spec_content, str):
            try:
                data = yaml.safe_load(spec_content)
            except Exception as exc:
                raise IRValidatorException(f"Failed to parse YAML: {exc}")
        elif isinstance(spec_content, dict):
            data = spec_content
        else:
            raise IRValidatorException("Spec content must be a string or dict")

        # Define required fields for the spec
        required_fields = ["name", "version", "components"]
        missing = [field for field in required_fields if field not in data]
        if missing:
            raise IRValidatorException(f"Missing required fields: {', '.join(missing)}")

        return data

def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    if not yaml_file:
        raise IRValidatorException("No YAML file path provided")
    try:
        with open(yaml_file, "r") as f:
            data = yaml.safe_load(f)
    except Exception as exc:
        raise IRValidatorException(f"Failed to read YAML file '{yaml_file}': {exc}") from exc

    if not isinstance(data, dict):
        raise IRValidatorException("YAML file does not contain a top-level dictionary")

    required = getattr(cls, "REQUIRED_FIELDS", [])
    missing = [field for field in required if field not in data]
    if missing:
        raise IRValidatorException(f"Missing required fields in YAML file: {', '.join(missing)}")

    return data

def _include_groups(self, parser_dict):
        """Resolves the include dict directive in the spec files."""
        # Use a helper to handle recursion and avoid modifying the original dict
        visited = set()

        def _resolve(d):
            includes = d.get("include")
            if not includes:
                return d
            # Normalise to a list
            if isinstance(includes, str):
                includes = [includes]
            for inc in includes:
                if inc in visited:
                    raise ValueError(f"Circular include detected: {inc}")
                if inc not in getattr(self, "_groups", {}):
                    raise ValueError(f"Included group '{inc}' not found")
                visited.add(inc)
                # Make a shallow copy to avoid mutating the original group definition
                inc_def = dict(getattr(self, "_groups")[inc])
                # Resolve nested includes in the included group
                inc_resolved = _resolve(inc_def)
                # Merge the resolved group into the current dict
                for key, value in inc_resolved.items():
                    if key not in d:
                        d[key] = value
                visited.remove(inc)
            # Remove the include key after processing
            d.pop("include", None)
            return d

        return _resolve(parser_dict)

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    # Iterate over each argument defined in the spec
    for arg in self.spec.get('arguments', []):
        name = arg.get('name')
        if not name:
            continue

        # 1. Environment variable (highest priority)
        env_var = arg.get('env')
        if env_var and env_var in os.environ:
            defaults[name] = os.getenv(env_var)
            continue

        # 2. Spec-defined default
        if 'default' in arg:
            defaults[name] = arg['default']
            continue

        # 3. Configuration fallback (if available)
        if hasattr(self, 'config') and name in self.config:
            defaults[name] = self.config[name]

    return defaults

