def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    if not hasattr(self, 'commands'):
        raise AttributeError("Missing 'commands' attribute.")
    commands = self.commands
    if command_name not in commands:
        raise KeyError(f"Command '{command_name}' not found.")
    command = commands[command_name]
    # Determine the options container
    if isinstance(command, dict):
        options = command
    else:
        options = getattr(command, 'options', None)
        if options is None:
            # Fallback: assume the command object itself is a mapping of options
            options = command
    if argument_name not in options:
        raise KeyError(f"Option '{argument_name}' not found in command '{command_name}'.")
    return options[argument_name]

def _get_conditionally_required_args(self, command_name, options_spec, args):
        """
        List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options or a dict mapping
                              command names to option lists.
        :param args: the received input arguments (dict of option names to values)
        :return: list, list of argument names with matched ``required_when`` condition
        """
        # Resolve the option list for the given command
        if isinstance(options_spec, dict):
            opts = options_spec.get(command_name, [])
        else:
            opts = options_spec

        required = []
        for opt in opts:
            cond = opt.get('required_when')
            if cond is None:
                continue

            # If the condition is a callable, call it with the args dict
            if callable(cond):
                try:
                    if cond(args):
                        required.append(opt.get('name'))
                except Exception:
                    # ignore errors in condition evaluation
                    pass
            else:
                # Assume the condition is a string expression that can be evaluated
                # with the args dict as the local namespace.
                try:
                    if eval(cond, {}, args):
                        required.append(opt.get('name'))
                except Exception:
                    # ignore errors in condition evaluation
                    pass

        return required

def validate_length_args(self, args):
        """Check if value of arguments is not longer than length specified.

        :param args: The received arguments. Can be a dict mapping argument names to values
                     or a sequence of values. The maximum lengths are expected to be
                     defined in ``self.lengths`` as either a dict (for named arguments)
                     or a sequence (for positional arguments).
        :raises ValueError: If any argument value exceeds its specified maximum length.
        """
        # Helper to validate a single value against a maximum length
        def _check(name, value, max_len):
            if value is None:
                return
            try:
                length = len(value)
            except TypeError:
                # If the value has no length, skip validation
                return
            if max_len is not None and length > max_len:
                raise ValueError(
                    f"Argument '{name}' length {length} exceeds maximum allowed {max_len}"
                )

        # Retrieve the length specification from the instance
        lengths = getattr(self, "lengths", None)
        if lengths is None:
            # No length specification provided; nothing to validate
            return

        # If args is a mapping, use the mapping keys to look up lengths
        if isinstance(args, dict):
            for key, value in args.items():
                max_len = lengths.get(key) if isinstance(lengths, dict) else None
                _check(key, value, max_len)
        else:
            # Assume a sequence of positional arguments
            for idx, value in enumerate(args):
                if isinstance(lengths, (list, tuple)):
                    max_len = lengths[idx] if idx < len(lengths) else None
                else:
                    max_len = None
                _check(f"arg{idx}", value, max_len)

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Iterate over all defined arguments that may have a 'choices' constraint
    for arg_name, arg_def in getattr(self, "arguments", {}).items():
        # Skip arguments without a choices specification
        if "choices" not in arg_def:
            continue

        choices = arg_def["choices"]

        # Retrieve the value supplied for this argument from the args container
        if isinstance(args, dict):
            value = args.get(arg_name)
        else:
            value = getattr(args, arg_name, None)

        # If no value was supplied, nothing to validate
        if value is None:
            continue

        # If the value is an iterable (but not a string), validate each element
        if isinstance(value, (list, tuple, set)):
            for v in value:
                if v not in choices:
                    raise ValueError(
                        f"Invalid choice for argument '{arg_name}': {v}. "
                        f"Allowed choices: {choices}"
                    )
        else:
            # Single value validation
            if value not in choices:
                raise ValueError(
                    f"Invalid choice for argument '{arg_name}': {value}. "
                    f"Allowed choices: {choices}"
                )

def validate_min_max_args(self, args):
    """
    Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments. Can be a dict of argument names to values
                 or an iterable of values.
    :raises ValueError: If any numeric argument is outside the [self.min, self.max] range.
    :return: True if all arguments are within bounds.
    """
    # Determine if args is a mapping (dict-like) or an iterable of values
    if hasattr(args, "items"):
        iterable = args.items()
    else:
        iterable = enumerate(args)

    for key, value in iterable:
        # Skip non-numeric values
        if not isinstance(value, (int, float)):
            continue
        if value < self.min or value > self.max:
            raise ValueError(
                f"Argument {key}={value} is out of bounds [{self.min}, {self.max}]"
            )
    return True

def get_nested_custom_and_control_args(self, args):
    """
    Split input arguments into control and nested arguments.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file.
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list or dict of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}

    # Accept either a dict or a list of (key, value) tuples
    if isinstance(args, dict):
        items = args.items()
    elif isinstance(args, (list, tuple)):
        items = args
    else:
        # Unsupported type; return empty dicts
        return control_args, nested_args

    for key, value in items:
        if isinstance(key, str) and key.startswith("control_"):
            control_args[key] = value
        else:
            nested_args[key] = value

    return control_args, nested_args

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    import json, subprocess
    # Build the ansible-playbook command
    cmd = ['ansible-playbook', playbook_path]
    if verbose:
        # Add verbosity flags (e.g., -v, -vv, -vvv, etc.)
        cmd.extend(['-v'] * verbose)
    if ansible_args:
        for key, value in ansible_args.items():
            if isinstance(value, bool):
                if value:
                    cmd.append(f'--{key}')
            else:
                cmd.append(f'--{key}={value}')
    if extra_vars:
        # Pass extra variables as JSON
        cmd.extend(['--extra-vars', json.dumps(extra_vars)])
    # Execute the command in the workspace directory
    try:
        result = subprocess.run(
            cmd,
            cwd=getattr(ir_workspace, 'path', None),
            capture_output=True,
            text=True,
            check=True
        )
    except subprocess.CalledProcessError as exc:
        # Log the error output if the plugin provides a logger
        if hasattr(ir_plugin, 'log'):
            ir_plugin.log(exc.stdout)
            ir_plugin.log(exc.stderr)
        raise RuntimeError(f"ansible-playbook failed: {exc.stderr}") from exc
    # Optionally log the output
    if hasattr(ir_plugin, 'log'):
        ir_plugin.log(result.stdout)
    return result

def _convert_non_cli_args(self, parser_name, values_dict):
        """
        Casts arguments to correct types by modifying values_dict in place.
        By default all the values are strings.
        """
        # Define type mappings for known parsers
        type_map = {
            'main': {
                'verbose': bool,
                'count': int,
                'threshold': float,
            },
            'virsh': {
                'timeout': int,
                'force': bool,
            },
            'ospd': {
                'port': int,
                'debug': bool,
            },
        }

        # Helper to convert a string to a boolean
        def _to_bool(val):
            if isinstance(val, str):
                val_lower = val.strip().lower()
                if val_lower in ('true', '1', 'yes', 'y'):
                    return True
                if val_lower in ('false', '0', 'no', 'n'):
                    return False
            return bool(val)

        # Get the mapping for the current parser
        parser_map = type_map.get(parser_name, {})

        for key, val in list(values_dict.items()):
            # If we have a specific type for this key, use it
            if key in parser_map:
                target_type = parser_map[key]
                try:
                    if target_type is bool:
                        values_dict[key] = _to_bool(val)
                    else:
                        values_dict[key] = target_type(val)
                except Exception:
                    # If conversion fails, leave the original value
                    pass
                continue

            # Generic conversion for unknown keys
            if isinstance(val, str):
                # Try boolean conversion first
                val_lower = val.strip().lower()
                if val_lower in ('true', 'false', '1', '0', 'yes', 'no', 'y', 'n'):
                    values_dict[key] = _to_bool(val)
                    continue
                # Try integer conversion
                try:
                    int_val = int(val)
                    values_dict[key] = int_val
                    continue
                except ValueError:
                    pass
                # Try float conversion
                try:
                    float_val = float(val)
                    values_dict[key] = float_val
                    continue
                except ValueError:
                    pass

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    def _flatten(d, parent_key=''):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}.{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key))
            else:
                items[new_key] = v
        return items

    spec_file = None
    for fname in ('plugin.json', 'plugin.yaml', 'plugin.yml'):
        path = os.path.join(plugin_dir, fname)
        if os.path.isfile(path):
            spec_file = path
            break

    if not spec_file:
        return {}

    try:
        with open(spec_file, 'r', encoding='utf-8') as f:
            if spec_file.endswith('.json'):
                data = json.load(f)
            else:
                # Attempt to parse YAML if available
                try:
                    import yaml
                    data = yaml.safe_load(f)
                except Exception:
                    return {}
    except Exception:
        return {}

    if not isinstance(data, dict):
        return {}

    return _flatten(data)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    if not os.getenv('CONFIG_PATH'):
        # Default to a config file in the current working directory
        default_path = os.path.join(os.getcwd(), 'config.yaml')
        os.environ['CONFIG_PATH'] = default_path

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if path is None or root is None:
        raise ValueError("path and root must not be None")
    # Normalize root: strip trailing slashes/backslashes
    norm_root = root.rstrip('/\\')
    # If root is empty after stripping, just return path
    if not norm_root:
        return path
    # If path equals root exactly
    if path == norm_root:
        return ''
    # Check for root + separator
    for sep in ('/', '\\'):
        prefix = norm_root + sep
        if path.startswith(prefix):
            return path[len(prefix):]
    # If no match, raise
    raise ValueError(f"Path {path!r} does not start with root {root!r}")
